-- C11 | age on a reference date
-- Question : What is the total revenue excluding VAT, in euro cents, generated by customers who are exactly 25 years old on the reference date 2026-12-01 (all their orders)?
--
-- Auteur          : Sharusan Rasakaran
-- Vérifié par     : Ayoub
-- Vérification    : calcul indépendant en Python pur sur les CSV (446690)

SELECT COALESCE(SUM(o.quantity_product * p.price), 0) AS revenue_cents
FROM orders o
JOIN customers c ON c.customer_id = o.customer_id
JOIN product p ON p.product_id = o.product_id
WHERE (2026 - CAST(substr(c.birth_date,1,4) AS INTEGER))
      - ('12-01' < substr(c.birth_date,6,5)) = 25;

-- Résultat : revenue_cents = 446690
